"""The categories. Each one is a prompt with clear edges, so a right answer is easy to check.

  id, name, icon, q     the prompt ("**bold**" is highlighted)
  src                   Wikidata sources (see wiki.py)
  br                    Brain Rocket topic ids whose hand-made lists also count (and hint at tiers)
  strip                 words players add that should be ignored ("beagle dog")
  junk                  the famous "obscure" picks everyone reaches for: Space Junk
  gem                   the one Supernova answer
  drop / drop_re        answers to leave out (by name, or a regex on the Wikipedia title)
  min_links             leave out items with fewer Wikipedia pages than this (trims junk entries)
  pad                   share of answers that are Launch Pad (default 3.5%, at most pad_max = 14)
  short                 allow 2-letter aliases (element symbols, state codes)
  trim                  a regex cut off the end of shown names ("Saab Automobile" -> "Saab")
  nick                  nicknames and slang Wikidata doesn't record: {answer: [nickname, …]}
"""
HUMAN = 'P31=Q5'
# sovereign states that still exist (no dissolution date), optionally on one continent
NOW = '{ ?item wdt:P31 wd:Q3624078 . FILTER NOT EXISTS { ?item wdt:P576 [] } %s }'


def big(cond, n):
    """A large class, cut down in the query itself to items with at least n Wikipedia pages."""
    trip = ' '.join(f'?item wdt:{a} wd:{b} .' for a, b in (x.split('=') for x in cond.split()))
    return '{ %s ?item wikibase:sitelinks ?n . FILTER(?n >= %d) }' % (trip, n)


def taxa(group, n, rank='Q7432'):
    """Species (or another rank) anywhere under a group, with at least n Wikipedia pages."""
    return '{ ?item wdt:P171+ wd:%s ; wdt:P105 wd:%s ; wikibase:sitelinks ?n . FILTER(?n >= %d) }' % (group, rank, n)

